import{_ as e,o as d,c as o,a5 as a}from"./chunks/framework.CcrBcQWS.js";const b=JSON.parse('{"title":"Low Level (RL 정책) — C++ 예제","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/software/sdk/cpp/low-level.md","filePath":"ko/software/sdk/cpp/low-level.md","lastUpdated":1787021357000}'),s={name:"ko/software/sdk/cpp/low-level.md"};function i(r,t,l,n,c,h){return d(),o("div",null,[...t[0]||(t[0]=[a(`<h1 id="low-level-rl-정책-—-c-예제" tabindex="-1">Low Level (RL 정책) — C++ 예제 <a class="header-anchor" href="#low-level-rl-정책-—-c-예제" aria-label="Permalink to &quot;Low Level (RL 정책) — C++ 예제&quot;">​</a></h1><p><strong>소스</strong>: <code>rbq_sdk/cpp/example/src/rbq_low_level.cpp</code></p><p>IMU, 조이스틱, 다리 관절 피드백 토픽을 구독하고, 관절 위치 레퍼런스와 소유권 명령을 발행하며, 선택적으로 **학습된 보행 정책(ONNX)**을 실행하는 저수준 관절 제어 예제입니다.</p><h2 id="동작-개요" tabindex="-1">동작 개요 <a class="header-anchor" href="#동작-개요" aria-label="Permalink to &quot;동작 개요&quot;">​</a></h2><p>애플리케이션은 단일 <strong>500 Hz 제어 루프</strong> (2 ms 주기)와 키보드 기반 상태 머신으로 구성됩니다:</p><table tabindex="0"><thead><tr><th>상태</th><th>키</th><th>제어 루프 동작</th></tr></thead><tbody><tr><td><strong>Idle</strong></td><td>—</td><td>스택의 최종 레퍼런스(<code>rt/rbq/ref/motion/_0</code>)를 추적하고 재발행 — 투명한 패스스루 역할</td></tr><tr><td><strong>Motion</strong></td><td><code>x</code> / <code>z</code></td><td><code>JointControl</code> 코사인 궤적을 사용해 <code>ready</code> 또는 <code>ground</code> 자세로 관절 보간</td></tr><tr><td><strong>Control</strong></td><td><code>c</code></td><td>ONNX 정책 로드, <strong>100 Hz</strong>로 추론 실행 (2 ms 루프의 5번 데시메이션), 정책 게인으로 <code>MotionRef</code> 발행</td></tr></tbody></table><h2 id="사전-요구사항" tabindex="-1">사전 요구사항 <a class="header-anchor" href="#사전-요구사항" aria-label="Permalink to &quot;사전 요구사항&quot;">​</a></h2><ul><li>RBQ SDK 빌드 및 설치 완료 — <a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a> 참조.</li><li><strong>onnxruntime</strong> 라이브러리 — <code>rbq_sdk/cpp/example/scripts/setup.bash</code> 로 설치됩니다.</li><li><code>info.json</code>과 <code>policy.onnx</code>가 들어있는 정책 디렉토리.</li><li>로봇 스택이 실행 중(시뮬레이션 또는 하드웨어).</li></ul><h2 id="빌드" tabindex="-1">빌드 <a class="header-anchor" href="#빌드" aria-label="Permalink to &quot;빌드&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/setup.bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/build.bash</span></span></code></pre></div><p>바이너리: <code>bin/rbq_low_level</code></p><h2 id="실행" tabindex="-1">실행 <a class="header-anchor" href="#실행" aria-label="Permalink to &quot;실행&quot;">​</a></h2><p><code>rbq_sdk/cpp/example/</code>에서:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># RT 스레드를 위해 root 권한 필요; sudo 없이 실행하면 일반 스레드 사용</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bin/rbq_low_level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">정책디렉토</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">리</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 사전 학습된 정책 사용:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bin/rbq_low_level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../rbq_simulator/rbq_gym/policy/rbq10/</span></span></code></pre></div><p><code>-p</code> 옵션은 <strong>필수</strong>입니다. 없으면 프로그램이 에러와 함께 종료됩니다.</p><h2 id="시뮬레이션으로-실행" tabindex="-1">시뮬레이션으로 실행 <a class="header-anchor" href="#시뮬레이션으로-실행" aria-label="Permalink to &quot;시뮬레이션으로 실행&quot;">​</a></h2><ol><li><code>RBQ/</code>에서 전체 스택 시작:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/sim.bash</span></span></code></pre></div></li><li>RBQGUI에서 <strong>Connect</strong> → <strong>Auto Start Robot</strong> → <strong>Stance</strong> (<code>2</code>).</li><li><code>rbq_sdk/cpp/example/</code>에서:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./bin/rbq_low_level</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ../../rbq_simulator/rbq_gym/policy/rbq10/</span></span></code></pre></div></li></ol><h2 id="키보드-제어" tabindex="-1">키보드 제어 <a class="header-anchor" href="#키보드-제어" aria-label="Permalink to &quot;키보드 제어&quot;">​</a></h2><table tabindex="0"><thead><tr><th>키</th><th>동작</th></tr></thead><tbody><tr><td><code>q</code></td><td>종료</td></tr><tr><td><code>z</code></td><td><strong>ground</strong> 자세로 이동 (접기 → 지면, ~4.8 s)</td></tr><tr><td><code>x</code></td><td><strong>ready</strong> 자세로 이동 (지면 → 접기 → 준비, ~2.8–5.6 s)</td></tr><tr><td><code>c</code></td><td><strong>Walk / Control</strong> 모드 시작 (<code>-p</code> 경로의 정책 로드)</td></tr></tbody></table><p>비캐노니컬 터미널 I/O(non-canonical, no echo)를 사용하므로 Enter 없이 키 입력 즉시 반응합니다.</p><h2 id="정책-디렉토리" tabindex="-1">정책 디렉토리 <a class="header-anchor" href="#정책-디렉토리" aria-label="Permalink to &quot;정책 디렉토리&quot;">​</a></h2><p><code>-p</code> 디렉토리에는 다음 파일들이 있어야 합니다:</p><table tabindex="0"><thead><tr><th>파일</th><th>용도</th></tr></thead><tbody><tr><td><code>info.json</code></td><td>정책 하이퍼파라미터 (<code>run_name</code>, <code>policy_dt</code>, <code>action_scale</code>, 강성/댐핑, 관측/행동 크기, 정규화 스케일, 기본 관절 각도, 명령 범위)</td></tr><tr><td><code>policy.onnx</code></td><td>학습 프레임워크에서 내보낸 ONNX 모델</td></tr></tbody></table><p>지원되는 정책 이름 (<code>info.json</code>의 <code>run_name</code>):</p><table tabindex="0"><thead><tr><th>이름</th><th>관측 벡터</th><th>비고</th></tr></thead><tbody><tr><td><code>rbq10</code></td><td>gyro, proj_grav, command, dof_pos, dof_vel, action</td><td>단일 프레임</td></tr><tr><td><code>rbq10_trot</code></td><td>gyro, proj_grav, command, 4×dof_pos 히스토리(0,2,4,6), 4×dof_vel 히스토리, action×2, added_mass</td><td>7프레임 히스토리, 데시메이션 5</td></tr><tr><td><code>rbq10_trot_run</code></td><td><code>rbq10_trot</code>과 동일</td><td>고속 런 변형</td></tr></tbody></table><h2 id="dds-토픽" tabindex="-1">DDS 토픽 <a class="header-anchor" href="#dds-토픽" aria-label="Permalink to &quot;DDS 토픽&quot;">​</a></h2><table tabindex="0"><thead><tr><th>방향</th><th>토픽</th><th>타입</th><th>설명</th></tr></thead><tbody><tr><td>구독</td><td><code>rt/rbq/joy</code></td><td><code>Joy_</code></td><td>속도 명령용 조이스틱 축 값</td></tr><tr><td>구독</td><td><code>rt/rbq/imu</code></td><td><code>Imu_</code></td><td>각속도 + 자세 쿼터니언</td></tr><tr><td>구독</td><td><code>rt/rbq/leg_joint</code></td><td><code>LegJointInfo_</code></td><td>관절 위치 및 속도 (12개)</td></tr><tr><td>구독</td><td><code>rt/rbq/ref/motion/_0</code></td><td><code>MotionRef_</code></td><td>최종 블렌딩 레퍼런스 (Idle에서 사용)</td></tr><tr><td>발행</td><td><code>rt/rbq/ref/motion/_20</code></td><td><code>MotionRef_</code></td><td>PD 게인이 포함된 관절 위치 레퍼런스</td></tr><tr><td>발행</td><td><code>rt/rbq/cmd/motion/owner/_20</code></td><td><code>JointOwnershipCmd_</code></td><td>12개 관절 소유권 요청</td></tr></tbody></table><h2 id="관절-인덱스-순서" tabindex="-1">관절 인덱스 순서 <a class="header-anchor" href="#관절-인덱스-순서" aria-label="Permalink to &quot;관절 인덱스 순서&quot;">​</a></h2><p>관절은 0–11 순서로 인덱싱됩니다:</p><p><code>HR</code> (후우측): <code>HRR(0)</code>, <code>HRP(1)</code>, <code>HRK(2)</code> →<br><code>HL</code> (후좌측): <code>HLR(3)</code>, <code>HLP(4)</code>, <code>HLK(5)</code> →<br><code>FR</code> (전우측): <code>FRR(6)</code>, <code>FRP(7)</code>, <code>FRK(8)</code> →<br><code>FL</code> (전좌측): <code>FLR(9)</code>, <code>FLP(10)</code>, <code>FLK(11)</code></p><h2 id="주요-구현-사항" tabindex="-1">주요 구현 사항 <a class="header-anchor" href="#주요-구현-사항" aria-label="Permalink to &quot;주요 구현 사항&quot;">​</a></h2><ul><li><strong>RT 스레드</strong>: root로 실행 시 <code>rbq_sdk::Thread::generate_rt_thread</code>를 사용해 SCHED_FIFO 스케줄링을 적용합니다. root 없이 실행하면 일반 <code>std::thread</code>를 사용합니다.</li><li><strong>소유권(Ownership)</strong>: Motion 또는 Control 상태로 전환할 때 <code>JointOwnershipCmd_</code>를 한 번 발행하여 12개 관절 전체를 요청합니다 (<code>owner_20</code> 우선순위).</li><li><strong>자세 감지</strong>: <code>goToMotionReady()</code>는 4개 고관절 피치 각도를 60° 기준으로 비교해 로봇이 현재 지면에 접혀있는지 확인하고, 필요시 접기 단계를 추가합니다.</li><li><strong>데시메이션</strong>: 정책은 2 ms 루프에서 5번에 한 번 (100 Hz)씩 실행되며, 이는 <code>info.json</code>의 <code>policy_dt</code>와 일치합니다.</li></ul><h2 id="문제-해결" tabindex="-1">문제 해결 <a class="header-anchor" href="#문제-해결" aria-label="Permalink to &quot;문제 해결&quot;">​</a></h2><table tabindex="0"><thead><tr><th>문제</th><th>가능한 원인</th></tr></thead><tbody><tr><td>움직임 없음 / 토픽 없음</td><td>스택이 실행 중이지 않거나 잘못된 네트워크 인터페이스</td></tr><tr><td><code>Policy, PolicyParams not loaded</code></td><td><code>-p</code> 경로 오류, <code>info.json</code>/<code>policy.onnx</code> 누락 또는 잘못된 형식</td></tr><tr><td><code>Thread deadline … over!</code></td><td>2 ms 주기 유지 불가 — sudo로 실행(RT 스레드) 또는 시스템 부하 감소</td></tr><tr><td>apt 인증 오류</td><td>호스트 GPG 문제와 무관; 별도로 수정 필요</td></tr></tbody></table><h2 id="관련-문서" tabindex="-1">관련 문서 <a class="header-anchor" href="#관련-문서" aria-label="Permalink to &quot;관련 문서&quot;">​</a></h2><ul><li><a href="/RBQ/nightly/ko/software/sdk/cpp/high-level.html">High Level Command</a></li><li><a href="/RBQ/nightly/ko/software/sdk/cpp/overview.html">C++ SDK 개요</a></li><li><a href="/RBQ/nightly/ko/software/concept.html">개념 설명 — 저수준 / LV0</a></li></ul>`,37)])])}const k=e(s,[["render",i]]);export{b as __pageData,k as default};
